  "patient_id": "string",
  "source_data": {
    "provisional_diagnosis_raw": "string",
    "chief_complaint": "string",
    "clinical_history": "string",
    "subjective_notes": "string or null",
    "goals_raw": "string or null"
  },
  "extracted_fields": {
